using Distributions
using JSON
using Random

"""
    halfnormal_pdf( x, sigma )

Evaluate the half-normal probability density function.

The half-normal distribution is defined as

    X = |Z|,   where Z ~ Normal(0, σ)

which is equivalent to a truncated normal distribution

    Truncated( Normal(0, σ), 0, ∞ ).
"""
halfnormal_pdf( x, sigma ) = pdf( Truncated( Normal( 0.0, sigma ), 0.0, Inf ), x )

"""
    logrand( a, b )

Generate a log-uniform random number in the interval [a, b].
"""
logrand( a, b ) = exp( rand()*( log(b)-log(a) ) + log(a) )

"""
    gen( n, name )

Generate randomized half-normal PDF fixture data and write to file.

# Arguments

* `n::Integer`: number of random samples
* `name::AbstractString`: output filename
"""
function gen( n, name )
    X = Float64[]
    S = Float64[]
    Z = Float64[]

    # Ensure reproducibility:
    Random.seed!( 123456 )

    for i in 1:n
        # σ spans many orders of magnitude:
        sigma = logrand( 1.0e-6, 10.0 )

        # Sample x in units of σ to avoid trivial underflow:
        x = rand() * 10.0 * sigma

        push!( X, x )
        push!( S, sigma )
        push!( Z, halfnormal_pdf( x, sigma ) )
    end

    # Store data to be written to file:
    data = Dict([
        ( "x", X ),
        ( "sigma", S ),
        ( "expected", Z )
    ])

    # Output path relative to this script:
    filepath = joinpath( dirname(@__FILE__), name )

    # Write JSON:
    open( filepath, "w" ) do io
        write( io, JSON.json( data ) )
        write( io, "\n" )
    end
end

# Generate randomized fixtures:
gen( 1000, "data.json" )
